// Session-scoped workflow completion. Live integrations remain explicitly identified.
const completionRecords = {};
function completionRecord(){return completionRecords[selected] ||= {impacts:[],audit:[]};}
function uxText(en,ja){return interfaceLanguage==='ja'?ja:en;}
function recordDecision(stage,decision){completionRecord().audit.unshift({stage,decision,author:profile.name,time:new Date().toISOString()});}
function nextProjectAction(){
 if(!current().approved)return ['srs',uxText('Review and approve the SRS','SRSを確認して承認')];
 if(backlog().rows.some(r=>r.status!=='Approved'))return ['requirements',uxText('Review draft requirements','下書き要件を確認')];
 if(approvedRequirements().some(r=>!r.userStory?.trim()))return ['stories',uxText('Complete user stories','ユーザーストーリーを作成')];
 if(!generatedTimelines[selected])return ['timeline',uxText('Prepare the timeline','スケジュールを作成')];
 if(timelineDecisions().estimate!=='Approved')return ['timeline-result',uxText('Review the estimated timeline','見積もりを確認')];
 if(architectureDraft().status!=='Approved')return ['architecture',uxText('Review architecture','アーキテクチャを確認')];
 return ['tests',uxText('Run and review test cases','テストを実行・確認')];
}
function projectNextPanel(){if(!selected)return '';const rows=hierarchyRows(),n=nextProjectAction(),log=completionRecord().audit;return '<section class="panel completion-overview"><div><small>'+uxText('SELECTED PROJECT','選択中のプロジェクト')+'</small><h2>'+esc(appProject().name)+'</h2><p>'+esc(n[1])+'</p>'+button(uxText('Open next action →','次の操作へ →'),"navigate('"+n[0]+"')",true)+'</div><div class="completion-metrics"><article><strong>'+rows.filter(r=>r.status==='Approved').length+'/'+rows.length+'</strong><span>'+uxText('Requirements approved','承認済み要件')+'</span></article><article><strong>'+completionRecord().impacts.filter(i=>!i.resolved).length+'</strong><span>'+uxText('Changes to review','確認が必要な変更')+'</span></article><article><strong>'+log.length+'</strong><span>'+uxText('Decisions this session','このセッションの承認履歴')+'</span></article></div></section>';}
for(const route of ['dashboard','projects']){const page=blueprintPageRoutes[route];if(page)blueprintPageRoutes[route]=function(){return projectNextPanel()+page();};}
const invalidateWithImpact=invalidateRequirement;
invalidateRequirement=function(r){invalidateWithImpact(r);completionRecord().impacts.unshift({id:r.id,name:r.story,time:new Date().toISOString(),resolved:false});backlog().approved=false;timelineDecisions().estimate='Pending';reviews().pm=false;architectureDraft().status='Draft';architectureState().approved=false;};
function resolveChange(index){completionRecord().impacts[index].resolved=true;recordDecision('Change review','Reviewed '+completionRecord().impacts[index].id);render();}
function impactPanel(){const entries=completionRecord().impacts.map((x,i)=>({...x,index:i})).filter(x=>!x.resolved);if(!entries.length)return '';return '<section class="panel completion-impact"><h2>'+uxText('Requirements changed — review related work','要件が変更されました：関連する成果物を確認')+'</h2><p>'+uxText('Timeline and architecture approvals were reset. Review stories, acceptance criteria and tests before approving the updated plan.','スケジュールとアーキテクチャの承認を解除しました。ストーリー、受入基準、テストを確認してください。')+'</p>'+entries.map(x=>'<div class="completion-impact-row"><span><b>'+esc(x.id)+'</b> · '+esc(x.name)+'</span>'+button(uxText('Mark reviewed','確認済みにする'),'resolveChange('+x.index+')')+'</div>').join('')+'</section>';}
for(const route of ['requirements','stories','timeline-result','architecture','tests','quality']){const page=blueprintPageRoutes[route];blueprintPageRoutes[route]=function(){return (selected?impactPanel():'')+page();};}
const approveRequirementRecorded=approveRequirement;
approveRequirement=function(id){approveRequirementRecorded(id);recordDecision('Requirement',id+' approved');};
const approveTimelineRecorded=approveTimelineStage;
approveTimelineStage=function(stage){approveTimelineRecorded(stage);if(timelineDecisions()[stage]==='Approved')recordDecision('Timeline','Approved');};
function viewDecisionLog(){const b=document.getElementById('modal');b.className='history-dialog';b.innerHTML='<div class="history-heading"><h2>'+uxText('Decision history','承認履歴')+'</h2><button aria-label="Close" onclick="document.getElementById(\'modal\').close()">×</button></div><div class="history-body">'+(completionRecord().audit.map(a=>'<article class="history-card"><b>'+esc(a.stage+' · '+a.decision)+'</b><p>'+esc(a.author)+' · '+new Date(a.time).toLocaleString()+'</p></article>').join('')||'<p>'+uxText('No decisions recorded in this session.','このセッションには履歴がありません。')+'</p>')+'</div>';b.showModal();}
function meetingReviewFields(){const d=requestDraft();d.review ||= {summary:'',decisions:'',actions:''};return '<div class="completion-review-fields">'+[['summary','Meeting summary','会議の要約'],['decisions','Decisions and open questions','決定事項と未解決の質問'],['actions','Action items and owners','アクションと担当者']].map(([key,en,ja])=>'<label class="field">'+uxText(en,ja)+'<textarea oninput="requestDraft().review.'+key+'=this.value">'+esc(d.review[key])+'</textarea></label>').join('')+'</div>';}
function meetingReviewPage(){const d=requestDraft();return appNav()+bpHeading(uxText('Review meeting results','会議の結果を確認'),uxText('Edit the transcript and capture decisions before preparing your SRS.','SRSの作成前に文字起こしと決定事項を確認してください。'),button(uxText('Back to inputs','入力に戻る'),"navigate('request')"))+'<section class="panel completion-meeting"><div class="completion-success"><span>✓</span><div><h2>'+esc(d.title||'Meeting results')+'</h2><p>'+uxText('Transcript included automatically in this project’s SRS context.','文字起こしはこのプロジェクトのSRSに自動的に含まれます。')+'</p></div></div><p class="notice">'+uxText('Demo transcript. No audio was captured, so recording playback is unavailable.','デモの文字起こしです。音声は収録していないため、再生できません。')+'</p><h3>'+uxText('Speaker transcript','話者別の文字起こし')+'</h3><div class="completion-transcript">'+d.entries.map((row,i)=>'<article><label class="field">'+uxText('Speaker','話者')+'<input aria-label="Speaker '+(i+1)+'" value="'+esc(row[0])+'" oninput="requestDraft().entries['+i+'][0]=this.value"></label><label class="field">English<textarea oninput="requestDraft().entries['+i+'][1]=this.value">'+esc(row[1])+'</textarea></label><label class="field">日本語<textarea oninput="requestDraft().entries['+i+'][2]=this.value">'+esc(row[2])+'</textarea></label></article>').join('')+'</div>'+meetingReviewFields()+'<div class="completion-footer">'+button(uxText('Download transcript','文字起こしをダウンロード'),'downloadMeetingTranscript()')+button(uxText('Continue to SRS →','SRSへ進む →'),'continueRequest()',true)+'</div></section>';}
pageNames['meeting-review']='Review meeting results';blueprintPageRoutes['meeting-review']=meetingReviewPage;
function downloadMeetingTranscript(){const d=requestDraft(),text=d.entries.map(r=>r[0]+'\nEN: '+r[1]+'\nJA: '+r[2]).join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='meeting-transcript.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const combineWithReview=combinedRequestContext;
combinedRequestContext=function(r,d){return [combineWithReview(r,d),...Object.entries(d.review||{}).filter(([k,v])=>v.trim()).map(([k,v])=>k+'\n'+v)].filter(Boolean).join('\n\n');};
const stopForReview=stopContextMeeting;
stopContextMeeting=function(){stopForReview();if(requestDraft().entries.length)navigate('meeting-review');};
const meetingWithReview=contextMeeting;
contextMeeting=function(){const d=requestDraft();return meetingWithReview()+(!d.running&&d.entries.length?'<div class="completion-footer"><p>'+uxText('Your transcript is ready. Review it before generating the SRS.','文字起こしの準備ができました。SRSを生成する前に確認してください。')+'</p>'+button(uxText('Review meeting results →','会議の結果を確認 →'),"navigate('meeting-review')",true)+'</div>':'');};
// Record actual execution separately from test definitions.
const testEditorBeforeExecution=editTestCase;
editTestCase=function(rid,cid=''){testEditorBeforeExecution(rid,cid);const r=eligibleTests().find(r=>r.id===rid);if(!r)return;const c=casesForRequirement(r).find(c=>c.id===cid);creationPage.body+='<label class="field">'+uxText('Preconditions','事前条件')+'<textarea name="preconditions">'+esc(c?.preconditions||'')+'</textarea></label>';render();};
const testSaveBeforeExecution=saveTestCase;
saveTestCase=function(e,rid,cid){const conditions=String(new FormData(e.target).get('preconditions')||'');testSaveBeforeExecution(e,rid,cid);if(screen!=='tests')return;const r=eligibleTests().find(x=>x.id===rid),cases=casesForRequirement(r),c=cid?cases.find(c=>c.id===cid):cases.at(-1);if(c)c.preconditions=conditions;};
function executionDialog(rid,cid){const r=eligibleTests().find(x=>x.id===rid),c=casesForRequirement(r).find(x=>x.id===cid),box=document.getElementById('modal');box.className='history-dialog';box.innerHTML='<form onsubmit="saveExecution(event,\''+rid+'\',\''+cid+'\')"><div class="history-heading"><h2>'+esc(c.id)+' · '+uxText('Test execution','テスト実行')+'</h2></div><div class="form"><p>'+esc(c.name)+'</p><label class="field">'+uxText('Actual result','実際の結果')+'<textarea name="actual" required>'+esc(c.actual||'')+'</textarea></label><label class="field">'+uxText('Outcome','結果')+'<select name="status">'+['Not run','Passed','Failed','Blocked'].map(s=>'<option '+(c.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select></label><label class="field">'+uxText('Evidence URL (optional)','証跡URL（任意）')+'<input type="url" name="evidence" value="'+esc(c.evidence||'')+'"></label><label class="field">'+uxText('Defect reference (optional)','不具合番号（任意）')+'<input name="defect" value="'+esc(c.defect||'')+'"></label>'+(c.executedBy?'<p>'+esc(c.executedBy)+' · '+esc(c.executedAt)+'</p>':'')+'</div><div class="history-footer"><button type="button" onclick="document.getElementById(\'modal\').close()">'+uxText('Cancel','キャンセル')+'</button><button class="primary">'+uxText('Save execution','実行結果を保存')+'</button></div></form>';box.showModal();}
function saveExecution(e,rid,cid){e.preventDefault();const r=eligibleTests().find(x=>x.id===rid),c=casesForRequirement(r).find(x=>x.id===cid),f=new FormData(e.target);Object.assign(c,{actual:String(f.get('actual')).trim(),status:String(f.get('status')),evidence:String(f.get('evidence')),defect:String(f.get('defect')),executedBy:profile.name,executedAt:new Date().toISOString()});document.getElementById('modal').close();captureProjectVersion('tests','Test execution saved: '+cid);render();}
const testsBeforeExecution=blueprintPageRoutes.tests;
blueprintPageRoutes.tests=function(){let html=testsBeforeExecution();for(const r of eligibleTests())for(const c of casesForRequirement(r)){const edit=button('Edit',"editTestCase('"+r.id+"','"+c.id+"')");html=html.replace(edit,edit+button(uxText('Execution','実行結果'),"executionDialog('"+r.id+"','"+c.id+"')"));}return html;};
Object.assign(localizedLabels,{'Review meeting results':'会議の結果を確認','Back to inputs':'入力に戻る','Decision history':'承認履歴'});
render();
let completionMatrixFilter='all';
function traceabilityRows(){return hierarchyRows().map(r=>({r,cases:r.status==='Approved'?casesForRequirement(r):[],story:!!r.userStory?.trim(),criteria:!!r.ac?.trim()}));}
blueprintPageRoutes.traceability=function(){const all=traceabilityRows(),rows=all.filter(x=>completionMatrixFilter==='all'||(completionMatrixFilter==='gaps'?(!x.story||!x.criteria||!x.cases.length):x.r.status==='Approved'));return appNav()+bpHeading(uxText('Requirements traceability','要件トレーサビリティ'),uxText('Follow each requirement through stories, acceptance criteria and test execution.','要件、ストーリー、受入基準、テスト実行の関連を確認します。'),button(uxText('Export matrix · CSV','マトリクス出力 · CSV'),'exportCompletionMatrix()'))+'<section class="panel completion-matrix"><div class="panel-title"><label>'+uxText('Show','表示')+' <select onchange="completionMatrixFilter=this.value;render()">'+[['all','All requirements','すべての要件'],['gaps','Coverage gaps','カバレッジの不足'],['approved','Approved only','承認済みのみ']].map(([v,en,ja])=>'<option value="'+v+'" '+(completionMatrixFilter===v?'selected':'')+'>'+uxText(en,ja)+'</option>').join('')+'</select></label><span>'+rows.length+' / '+all.length+'</span></div><div class="requirement-table">'+table([uxText('Requirement','要件'),uxText('Approval','承認'),uxText('User story','ストーリー'),uxText('Acceptance criteria','受入基準'),uxText('Test cases','テストケース'),uxText('Results','結果')],rows.map(x=>[button(x.r.id+' · '+x.r.story,"editRequirement('"+x.r.id+"')"),badge(x.r.status),x.r.status==='Approved'?button(x.story?uxText('View story','ストーリー表示'):uxText('Missing','未作成'),"editStory('"+x.r.id+"')"):uxText('Awaiting approval','承認待ち'),x.criteria?uxText('Defined','作成済み'):uxText('Missing','未作成'),x.cases.map(c=>button(c.id,"executionDialog('"+x.r.id+"','"+c.id+"')")).join(' ')||uxText('No coverage','テストなし'),x.cases.filter(c=>c.status==='Passed').length+'/'+x.cases.length+' '+uxText('passed','合格')]))+'</div></section>';};
function exportCompletionMatrix(){const rows=[["Requirement ID","Requirement","Parent","Status","User story","Acceptance criteria","Test cases","Passed","Failed"],...traceabilityRows().map(x=>[x.r.id,x.r.story,x.r.parentId||'',x.r.status,x.r.userStory||'',x.r.ac||'',x.cases.map(c=>c.id).join('; '),x.cases.filter(c=>c.status==='Passed').length,x.cases.filter(c=>c.status==='Failed').length])];const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a'),u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=u;a.download='traceability-matrix.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
const overviewBeforeAudit=projectNextPanel;
projectNextPanel=function(){return overviewBeforeAudit().replace('</section>','<div>'+button(uxText('Decision history','承認履歴'),'viewDecisionLog()')+'</div></section>');};
render();
const completionMatrixPage=blueprintPageRoutes.traceability;
blueprintPageRoutes.traceability=function(){return actionsAtTop(completionMatrixPage(),'traceability');};
function stageProgress(){const stages=[['srs','SRS'],['baseline','Baseline'],['requirements','Requirements'],['stories','Stories'],['timeline','Timeline'],['architecture','Architecture'],['tests','Tests'],['quality','QA']];const next=nextProjectAction().route;return '<div class="stage-progress" aria-label="Project progress">'+stages.map(([route,label],i)=>{const active=route===next;const done=stages.findIndex(s=>s[0]===next)>i;return '<button type="button" class="stage-step '+(active?'is-active ':'')+(done?'is-done':'')+'" onclick="navigate(\''+route+'\')"><span>'+(done?'✓':i+1)+'</span><small>'+label+'</small></button>'}).join('<i aria-hidden="true">›</i>')+'</div>';}
const overviewWithProgress=projectNextPanel;
projectNextPanel=function(){return overviewWithProgress().replace('<div class="completion-metrics">',''+stageProgress()+'<div class="completion-metrics">');};
render();
